#endif// MacApp#ifndef __MACAPPTYPES__#include "MacAppTypes.h"#endif#ifndef __UAPPLICATION__#include "UApplication.h"#endif#ifndef __UDOCUMENT__#include "UDocument.h"#endif#ifndef __UERRORMGR__#include "UErrorMgr.h"#endif#ifndef __UMACAPPGLOBALS#include "UMacAppGlobals.h"#endif#ifndef __UMACAPPUTILITIES__#include "UMacAppUtilities.h"#endif#ifndef __UVIEW__#include "UView.h"#endif#ifndef __Types_AC__#include <Types_AC.h>#endif// Toolbox#ifndef __FONTS__#include <Fonts.h>#endif#ifndef __QUICKDRAW__#include <Quickdraw.h>#endif// Compatibility Hacks#if UNIVERSAL_INTERFACES_VERSION < 0x0300enum {	kFontIDTimes	= times};#endif // UNIVERSAL_INTERFACES_VERSION < 0x0300//----------------------------------------------------------------------------------------// Constants//----------------------------------------------------------------------------------------enum{	kSignature = 'SS01',				// Application signature	kFileType  = 'SF01'				// File-type code used for document files created by this application};//----------------------------------------------------------------------------------------// TNothingApplication://----------------------------------------------------------------------------------------class TNothingApplication : public TApplication{public:	TNothingApplication();	virtual ~TNothingApplication();		virtual TDocument* DoMakeDocument(CommandNumber itsCommandNumber, TFile* itsFile);};//----------------------------------------------------------------------------------------// TDefaultView://----------------------------------------------------------------------------------------class TDefaultView : public TView{	MA_DECLARE_CLONE;	public:	virtual ~TDefaultView();		virtual void Draw(const CViewRect& area);		// Draws the view seen in the window. Every nonblank view MUST override this method.};//========================================================================================// CLASS TDefaultView//========================================================================================MA_DEFINE_CLASS(TDefaultView);//----------------------------------------------------------------------------------------// TDefaultView destructor//----------------------------------------------------------------------------------------TDefaultView::~TDefaultView(){}//----------------------------------------------------------------------------------------// TDefaultView::Draw: //----------------------------------------------------------------------------------------void TDefaultView::Draw(const CViewRect&){	::PenNormal();	::PenSize(10, 10);	::PenPat(CPattern_AC::DarkGray());	// Draw a dark gray frame	::MacFrameRect(GetQDExtent());	// Set font and size for subsequent display in the window	::TextFont(kFontIDTimes);	// use a nice outline font	::TextSize(72);	::MoveTo(45, 90);	// Draw the word 'MacApp®' in large type.	::DrawString("\pMacApp®");	// Restore the pen state.	::PenNormal();}//========================================================================================// CLASS TNothingApplication//========================================================================================//----------------------------------------------------------------------------------------// TNothingApplication constructor//----------------------------------------------------------------------------------------TNothingApplication::TNothingApplication() :	TApplication(kFileType, kSignature){	// So we can create the view object by name and	// So my view will be substituted when MacApp® creates the "default view"		REGISTER_SIGNATURE_AC(TDefaultView, kStdDefaultView);}//----------------------------------------------------------------------------------------// TNothingApplication destructor//----------------------------------------------------------------------------------------TNothingApplication::~TNothingApplication(){}//----------------------------------------------------------------------------------------// TNothingApplication::DoMakeDocument: //----------------------------------------------------------------------------------------TDocument* TNothingApplication::DoMakeDocument(CommandNumber, TFile* itsFile){	#pragma unused (itsFile)	return TH_new TDocument;}//========================================================================================// GLOBAL Functions//========================================================================================//----------------------------------------------------------------------------------------// main or WinMain//----------------------------------------------------------------------------------------#if qProjectBuilder	int main()#else	void main()#endif{	try	{		InitUMacApp(3);					// Initialize MacApp; 3 calls to MoreMasters		TNothingApplication aNothingApplication;		aNothingApplication.Run();	}	catch(CException_AC& theException)	{		DoCatchMessageAndStop_AC(theException);		::BailOutAlert(theException);	}	catch(std::exception& ex)			{		DoCatchISOMessageAndStop_AC(ex);		::BailOutAlert(ex);	}	catch(...)	{		DoCatchForeignMessageAndStop_AC();		::BailOutAlert();	}}//----------------------------------------------------------------------------------------// End of Nothing.cp/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/11/96	Added global scoping to toolbox calls.		06/01/96	[1327013] Changed application type back to SS01. It should							be this by default, since it does not define any type in any .r file.		----- R10 -----		03/18/96	Made better use of TView calls that return CRect_AC/VPoint/VRect		----- 3.3b1 -----		08/ 9/95	mrw		Changed app type 'SF01'->'SF00' (conflicted with Skeleton)		05/15/95	Add another call to MoreMasters. 		04/08/95	Need to include UDocument. 		04/06/95	Regroup Universal code initialization.		03/13/95	Change Free methods to destructors. 		02/24/95	Update comments. 		02/22/95	1208317 When reregistering the default view - use the constant		02/22/95	1222679 Nothing doesn't need to support disk files or printing		02/22/95	gNothingApplication replaced by a local aNothingApplication*/